//! Regenerates src/consts.rs: Poseidon constants and empty-subtree roots.
//! Run: cargo run -p tideover-zk --bin gen-consts --release

use std::{fs, path::PathBuf};
use tideover_zk::{encoding::fr_to_bytes, poseidon, tree, Fr};

fn arr(x: &Fr) -> String {
    let items: Vec<String> = fr_to_bytes(x).iter().map(|v| format!("{v:#04x}")).collect();
    format!("[{}]", items.join(", "))
}

fn main() {
    let cfg = poseidon::generate_config();
    let mut out = String::from(
        "//! GENERATED by `cargo run -p tideover-zk --bin gen-consts --release`. Do not edit.\n\
         //! Poseidon (BLS12-381 Fr, width 3, 8 full + 57 partial rounds, alpha 5) and the\n\
         //! empty-subtree roots. All values are canonical 32-byte little-endian field elements.\n\n",
    );
    out.push_str(&format!(
        "pub const POSEIDON_ARK: [[[u8; 32]; 3]; {}] = [\n",
        cfg.ark.len()
    ));
    for row in &cfg.ark {
        let cells: Vec<String> = row.iter().map(arr).collect();
        out.push_str(&format!("    [{}],\n", cells.join(", ")));
    }
    out.push_str("];\n\npub const POSEIDON_MDS: [[[u8; 32]; 3]; 3] = [\n");
    for row in &cfg.mds {
        let cells: Vec<String> = row.iter().map(arr).collect();
        out.push_str(&format!("    [{}],\n", cells.join(", ")));
    }
    out.push_str("];\n\n");
    let zeros = tree::compute_zeros_with(&cfg);
    out.push_str(&format!(
        "pub const TREE_ZEROS: [[u8; 32]; {}] = [\n",
        zeros.len()
    ));
    for z in &zeros {
        out.push_str(&format!("    {},\n", arr(z)));
    }
    out.push_str("];\n");
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src/consts.rs");
    fs::write(&path, out).unwrap();
    println!("wrote {}", path.display());
}
